import{describe,it,expect}from"vitest";import{CROPS_DATABASE}from"../../frontend/crop-journey/script.js";describe("Crop Journey Game Dataset & Agronomy Logic",()=>{it("should contain 12 major Indian crops across Kharif, Rabi, and Zaid seasons",()=>{expect(CROPS_DATABASE).toHaveLength(12);const e=CROPS_DATABASE.map(e=>e.season);expect(e).toContain("kharif"),expect(e).toContain("rabi"),expect(e).toContain("zaid"),CROPS_DATABASE.forEach(e=>{expect(e).toHaveProperty("id"),expect(e).toHaveProperty("name"),expect(e).toHaveProperty("season"),expect(e).toHaveProperty("seasonLabel"),expect(e).toHaveProperty("climate"),expect(e).toHaveProperty("states"),expect(e).toHaveProperty("harvestWindow"),expect(e).toHaveProperty("educationalInsight")})}),it("should verify Kharif monsoon crops (Paddy, Cotton, Soyabean)",()=>{const e=CROPS_DATABASE.find(e=>"rice"===e.id);expect(e.season).toBe("kharif"),expect(e.states).toContain("West Bengal");const t=CROPS_DATABASE.find(e=>"cotton"===e.id);expect(t.season).toBe("kharif"),expect(t.climate).toContain("Black Soil")}),it("should verify Rabi winter crops (Wheat, Mustard, Gram)",()=>{const e=CROPS_DATABASE.find(e=>"wheat"===e.id);expect(e.season).toBe("rabi"),expect(e.states).toContain("Punjab");const t=CROPS_DATABASE.find(e=>"mustard"===e.id);expect(t.season).toBe("rabi"),expect(t.states).toContain("Rajasthan")}),it("should verify Zaid summer crops (Watermelon, Cucumber)",()=>{const e=CROPS_DATABASE.find(e=>"watermelon"===e.id);expect(e.season).toBe("zaid"),expect(e.harvestWindow).toContain("May-June");const t=CROPS_DATABASE.find(e=>"cucumber"===e.id);expect(t.season).toBe("zaid")})});